package com.wasteinfoai.ai.vision

import kotlin.math.exp
import kotlin.math.ln
import kotlin.math.log2

/**
 * Result states for the rejection policy.
 */
enum class AcceptanceState {
    ACCEPTED,
    LOW_CONFIDENCE,
    LIKELY_NON_WASTE,
    OOD_SUSPECTED,
    AMBIGUOUS,
    INVALID_OUTPUT,
    INFERENCE_FAILED
}

/**
 * Detailed evaluation report generated by [PredictionAcceptancePolicy].
 */
data class PolicyEvaluationResult(
    val state: AcceptanceState,
    val isAccepted: Boolean,
    val confidence: Float,
    val top1Class: String,
    val top1ClassId: Int,
    val topMargin: Float,
    val entropy: Float,
    val normalizedEntropy: Float,
    val userFacingMessage: String,
    val diagnosticDetails: String,
    val shouldOfferManualSelection: Boolean,
    val shouldOfferRecapture: Boolean
)

/**
 * Versioned, configurable thresholds for prediction acceptance and OOD filtering.
 */
data class AcceptancePolicyConfig(
    val version: String = "2.0.0-calibrated",
    val confidenceThreshold: Float = 0.62f,
    val minMarginThreshold: Float = 0.15f,
    val maxNormalizedEntropy: Float = 0.70f,
    val oodConfidenceFloor: Float = 0.35f,
    val defaultRejectionMessage: String = "No clear waste item detected. Please position the item inside the frame and try again."
)

/**
 * Production rejection policy that inspects softmax output distributions,
 * computes predictive Shannon entropy and top-2 margin, and prevents out-of-distribution
 * or non-waste inputs from being forced into one of the 17 supported categories.
 */
class PredictionAcceptancePolicy(
    val config: AcceptancePolicyConfig = AcceptancePolicyConfig()
) {

    /**
     * Numerically stable softmax computation.
     */
    fun computeSoftmax(logits: FloatArray): FloatArray {
        if (logits.isEmpty()) return FloatArray(0)
        for (v in logits) {
            if (v.isNaN() || v.isInfinite()) {
                return FloatArray(0)
            }
        }

        val maxVal = logits.maxOrNull() ?: 0f
        var sumExp = 0.0
        val expScores = DoubleArray(logits.size)
        for (i in logits.indices) {
            val ev = exp((logits[i] - maxVal).toDouble())
            expScores[i] = ev
            sumExp += ev
        }
        if (sumExp <= 0.0 || sumExp.isNaN()) {
            return FloatArray(0)
        }

        return FloatArray(logits.size) { i ->
            (expScores[i] / sumExp).toFloat()
        }
    }

    /**
     * Shannon entropy H(p) = - sum(p_i * log2(p_i)).
     */
    fun calculateEntropy(probabilities: FloatArray): Float {
        var h = 0.0
        for (p in probabilities) {
            if (p > 1e-7f) {
                h -= p.toDouble() * log2(p.toDouble())
            }
        }
        return h.toFloat().coerceAtLeast(0f)
    }

    /**
     * Normalized entropy H(p) / log2(K) bounded in [0.0..1.0].
     */
    fun calculateNormalizedEntropy(probabilities: FloatArray): Float {
        if (probabilities.isEmpty()) return 1.0f
        val k = probabilities.size
        val maxH = if (k > 1) log2(k.toDouble()).toFloat() else 1.0f
        val entropy = calculateEntropy(probabilities)
        return (entropy / maxH).coerceIn(0f, 1f)
    }

    /**
     * Computes the score difference between the top-1 and top-2 predictions.
     */
    fun calculateMargin(rankedScores: List<ClassScore>): Float {
        if (rankedScores.size < 2) return rankedScores.firstOrNull()?.score ?: 0f
        return (rankedScores[0].score - rankedScores[1].score).coerceAtLeast(0f)
    }

    /**
     * Evaluates raw model output logits against the calibrated acceptance policy.
     */
    fun evaluate(
        logits: FloatArray,
        classLabels: List<String>
    ): PolicyEvaluationResult {
        if (logits.isEmpty()) {
            return PolicyEvaluationResult(
                state = AcceptanceState.INVALID_OUTPUT,
                isAccepted = false,
                confidence = 0f,
                top1Class = "Unknown",
                top1ClassId = -1,
                topMargin = 0f,
                entropy = 0f,
                normalizedEntropy = 1f,
                userFacingMessage = config.defaultRejectionMessage,
                diagnosticDetails = "Model returned empty output logits",
                shouldOfferManualSelection = true,
                shouldOfferRecapture = true
            )
        }

        for (v in logits) {
            if (v.isNaN() || v.isInfinite()) {
                return PolicyEvaluationResult(
                    state = AcceptanceState.INVALID_OUTPUT,
                    isAccepted = false,
                    confidence = 0f,
                    top1Class = "Unknown",
                    top1ClassId = -1,
                    topMargin = 0f,
                    entropy = 0f,
                    normalizedEntropy = 1f,
                    userFacingMessage = config.defaultRejectionMessage,
                    diagnosticDetails = "Logits contained non-finite values (NaN / Inf)",
                    shouldOfferManualSelection = true,
                    shouldOfferRecapture = true
                )
            }
        }

        val probabilities = computeSoftmax(logits)
        if (probabilities.isEmpty()) {
            return PolicyEvaluationResult(
                state = AcceptanceState.INVALID_OUTPUT,
                isAccepted = false,
                confidence = 0f,
                top1Class = "Unknown",
                top1ClassId = -1,
                topMargin = 0f,
                entropy = 0f,
                normalizedEntropy = 1f,
                userFacingMessage = config.defaultRejectionMessage,
                diagnosticDetails = "Softmax computation failed or produced invalid distribution",
                shouldOfferManualSelection = true,
                shouldOfferRecapture = true
            )
        }

        return evaluateProbabilities(probabilities, classLabels)
    }

    /**
     * Evaluates a valid probability distribution against rejection criteria.
     */
    fun evaluateProbabilities(
        probabilities: FloatArray,
        classLabels: List<String>
    ): PolicyEvaluationResult {
        val ranked = probabilities.indices
            .map { idx ->
                val label = if (idx < classLabels.size) classLabels[idx] else "Class_$idx"
                ClassScore(idx, label, probabilities[idx])
            }
            .sortedByDescending { it.score }

        val top1 = ranked.first()
        val top2Score = if (ranked.size > 1) ranked[1].score else 0f
        val margin = (top1.score - top2Score).coerceAtLeast(0f)
        val entropy = calculateEntropy(probabilities)
        val normEntropy = calculateNormalizedEntropy(probabilities)

        // Rule 1: Confidence below OOD floor -> LIKELY_NON_WASTE
        if (top1.score < config.oodConfidenceFloor) {
            return PolicyEvaluationResult(
                state = AcceptanceState.LIKELY_NON_WASTE,
                isAccepted = false,
                confidence = top1.score,
                top1Class = top1.label,
                top1ClassId = top1.classId,
                topMargin = margin,
                entropy = entropy,
                normalizedEntropy = normEntropy,
                userFacingMessage = config.defaultRejectionMessage,
                diagnosticDetails = "Peak confidence (${String.format("%.1f%%", top1.score * 100)}) is below OOD floor (${String.format("%.1f%%", config.oodConfidenceFloor * 100)}). Image likely contains scenery, hands, or non-waste items.",
                shouldOfferManualSelection = true,
                shouldOfferRecapture = true
            )
        }

        // Rule 2: Normalized entropy exceeds ceiling -> OOD_SUSPECTED
        if (normEntropy > config.maxNormalizedEntropy) {
            return PolicyEvaluationResult(
                state = AcceptanceState.OOD_SUSPECTED,
                isAccepted = false,
                confidence = top1.score,
                top1Class = top1.label,
                top1ClassId = top1.classId,
                topMargin = margin,
                entropy = entropy,
                normalizedEntropy = normEntropy,
                userFacingMessage = config.defaultRejectionMessage,
                diagnosticDetails = "Predictive entropy (${String.format("%.2f", normEntropy)}) indicates diffuse classification uncertainty across categories. Target object may be out-of-domain or heavily occluded.",
                shouldOfferManualSelection = true,
                shouldOfferRecapture = true
            )
        }

        // Rule 3: Insufficient margin between top-1 and top-2 -> AMBIGUOUS
        if (margin < config.minMarginThreshold) {
            val top2Label = if (ranked.size > 1) ranked[1].label else "None"
            return PolicyEvaluationResult(
                state = AcceptanceState.AMBIGUOUS,
                isAccepted = false,
                confidence = top1.score,
                top1Class = top1.label,
                top1ClassId = top1.classId,
                topMargin = margin,
                entropy = entropy,
                normalizedEntropy = normEntropy,
                userFacingMessage = "Ambiguous material detected. Could be ${top1.label} (${String.format("%.0f%%", top1.score * 100)}) or $top2Label (${String.format("%.0f%%", top2Score * 100)}). Please select the correct category.",
                diagnosticDetails = "Top-2 score margin (${String.format("%.2f", margin)}) is below minimum discriminative margin (${config.minMarginThreshold}).",
                shouldOfferManualSelection = true,
                shouldOfferRecapture = true
            )
        }

        // Rule 4: Top-1 score below calibrated acceptance threshold -> LOW_CONFIDENCE
        if (top1.score < config.confidenceThreshold) {
            return PolicyEvaluationResult(
                state = AcceptanceState.LOW_CONFIDENCE,
                isAccepted = false,
                confidence = top1.score,
                top1Class = top1.label,
                top1ClassId = top1.classId,
                topMargin = margin,
                entropy = entropy,
                normalizedEntropy = normEntropy,
                userFacingMessage = config.defaultRejectionMessage,
                diagnosticDetails = "Confidence (${String.format("%.1f%%", top1.score * 100)}) is below acceptance threshold (${String.format("%.1f%%", config.confidenceThreshold * 100)}).",
                shouldOfferManualSelection = true,
                shouldOfferRecapture = true
            )
        }

        // Rule 5: Fully Accepted
        return PolicyEvaluationResult(
            state = AcceptanceState.ACCEPTED,
            isAccepted = true,
            confidence = top1.score,
            top1Class = top1.label,
            top1ClassId = top1.classId,
            topMargin = margin,
            entropy = entropy,
            normalizedEntropy = normEntropy,
            userFacingMessage = "Item identified as ${top1.label}.",
            diagnosticDetails = "Passed all acceptance criteria (Conf: ${String.format("%.1f%%", top1.score * 100)}, Margin: ${String.format("%.2f", margin)}, NormEntropy: ${String.format("%.2f", normEntropy)})",
            shouldOfferManualSelection = false,
            shouldOfferRecapture = false
        )
    }
}
